CREATE MATERIALIZED VIEW spike.daily_mv UUID 'd04648ed-dbec-4e11-8e8c-b5ee71c4c383' TO spike.daily (`day` Date, `users` AggregateFunction(uniq, UInt32), `total` AggregateFunction(sum, Float64)) AS SELECT toDate(ts) AS day, uniqState(user_id) AS users, sumState(amount) AS total FROM spike.events GROUP BY day